def _eval(self, context: RuleContext) -> EvalResultType:
    result = []

    # Find the appropriate segment for analysis
    segment = context.segment

    # Find a with_compound_statement if available
    with_compound = next(segment.recursive_crawl("with_compound_statement"), None)
    if with_compound:
        segment = with_compound
    # Otherwise, look for other SQL statement types
    elif not segment.is_type("with_compound_statement", "set_expression", "select_statement"):
        select_statement = next(segment.recursive_crawl("select_statement"), None)
        if select_statement:
            segment = select_statement

    try:
        # Create a query tree from the segment
        query_tree = Query.from_segment(segment, context.dialect)
        if query_tree:
            # Begin analysis at the final, outer query
            queries_with_ctes = list(self._find_all_ctes(query_tree))
            self._visit_sources(query_tree)
            for query in queries_with_ctes:
                if query.ctes:
